const allInput = $input.all();
const results = [];

for (const item of allInput) {
  const d = item.json;
  const title = (d.title || '').substring(0, 200);
  const url = d.link || d.url || '';
  const date = (d.isoDate || d.pubDate || new Date().toISOString()).substring(0, 10);
  const snippet = (d.contentSnippet || d['content:encodedSnippet'] || '').replace(/<[^>]*>/g, '').substring(0, 300);

  let source = 'Other';
  if (url.includes('zenn.dev')) source = 'Zenn';
  else if (url.includes('hnrss.org') || url.includes('news.ycombinator')) source = 'Hacker News';
  else source = 'Hacker News';

  if (!title) continue;

  const requestBody = JSON.stringify({
    parent: { database_id: '2ff2570f-e49f-817d-8288-e7c8667641a9' },
    properties: {
      '\u30bf\u30a4\u30c8\u30eb': { title: [{ text: { content: title } }] },
      'URL': { url: url || null },
      '\u30ab\u30c6\u30b4\u30ea': { select: { name: '\u30c6\u30c3\u30af' } },
      '\u30bd\u30fc\u30b9': { rich_text: [{ text: { content: source } }] },
      '\u65e2\u8aad': { checkbox: false },
      '\u65e5\u4ed8': { date: { start: date } },
      '\u8981\u7d04': { rich_text: [{ text: { content: snippet } }] }
    }
  });
  results.push({ json: { requestBody, title, source } });
}

const zenn = results.filter(r => r.json.source === 'Zenn').slice(0, 10);
const hn = results.filter(r => r.json.source === 'Hacker News').slice(0, 10);
return [...zenn, ...hn];

const items = $input.all();
const results = [];
for (const item of items) {
  const { requestBody, title, source } = item.json;
  const body = JSON.parse(requestBody);
  const snippet = body.properties['\u8981\u7d04'].rich_text[0]?.text?.content || '';
  const prompt = `Translate this English tech article title and summary into natural Japanese. Keep technical terms in English where appropriate.\n\nTitle: ${title}\nSummary: ${snippet}\n\nRespond in JSON format only:\n{"title": "Japanese title here", "summary": "Japanese summary here"}`;
  const geminiBody = JSON.stringify({
    contents: [{ parts: [{ text: prompt }] }],
    generationConfig: { temperature: 0.2, maxOutputTokens: 500 }
  });
  results.push({
    json: { geminiBody, requestBody, title, source, originalSnippet: snippet }
  });
}
return results;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const geminiResponse = items[i].json;
  const original = $('PreparePrompt').all()[i].json;
  let translatedTitle = original.title;
  let translatedSummary = original.originalSnippet;
  try {
    const responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      translatedTitle = parsed.title || translatedTitle;
      translatedSummary = parsed.summary || translatedSummary;
    }
  } catch (e) {
    // fallback to original English
  }
  const body = JSON.parse(original.requestBody);
  body.properties['\u30bf\u30a4\u30c8\u30eb'].title[0].text.content = translatedTitle;
  body.properties['\u8981\u7d04'].rich_text[0].text.content = translatedSummary;
  results.push({
    json: {
      requestBody: JSON.stringify(body),
      title: translatedTitle,
      source: original.source
    }
  });
}
return results;
